def meilleure_note(notes):
    if not notes:
        return None
    meilleure = notes[0]
    for n in notes:
        if n > meilleure:
            meilleure = n
    return meilleure

def relire(lignes):
    remarques = []
    for numero, ligne in enumerate(lignes, 1):
        if len(ligne) > 79:
            remarques.append([numero, "ligne trop longue"])
        if "\t" in ligne:
            remarques.append([numero, "tabulation"])
        if "== None" in ligne or "!= None" in ligne:
            remarques.append([numero, "utiliser is None"])
    return remarques

def quantite(texte):
    texte = texte.strip()
    if not texte.isdigit() or int(texte) == 0:
        raise ValueError("quantité invalide : " + texte)
    return int(texte)

def noms_fautifs(lignes):
    fautifs = []
    for numero, ligne in enumerate(lignes, 1):
        texte = ligne.strip()
        if texte.startswith("def "):
            nom = texte[4:].split("(")[0].strip()
            if nom != nom.lower():
                fautifs.append([numero, nom])
    return fautifs
